/**
 * #5001 slice 1 (cor:acl:140:09, The Selection Grammar): the selection payload, pinned byte for byte.
 *
 * Expected bytes come from `src/lib/grantSelectionSignature.fixture.json`, generated by
 * `scripts/generate-grant-selection-fixture.py` (Python hashlib), never by the builder under test. The literal layout is
 * also rebuilt inline here from the spec's lines. Every refusal is a refusal, never a repair. P1-P3 of the #5001 plan.
 */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { GRANT_SIGNATURE_PAYLOAD_V1, grantSignaturePayloadBytes } from './grantPayload.js';
import {
  GRANT_SELECTION_CAP, GRANT_SELECTION_PAYLOAD_V1, grantSelectionPayloadBytes, type GrantSelectionItem,
} from './grantSelectionPayload.js';
import { SIGNATURE_PAYLOAD_V3, signatureChallenge, UnsupportedSignaturePayloadError } from './payload.js';

interface Case {
  name: string; selectionId: string; items: GrantSelectionItem[]; payloadUtf8: string; canonical: string;
  challengeHex: string; challengeBase64url: string;
}
const fixture = JSON.parse(readFileSync(new URL('../grantSelectionSignature.fixture.json', import.meta.url), 'utf8')) as {
  version: string; termsVersion: string; challengeAlgorithm: string; cap: number; cases: Case[];
};
const byName = (n: string) => fixture.cases.find((c) => c.name === n)!;
const H = '0ef8421dcdd63e2052bee076b041298658d05b293056afc33deee231d92d1c4f';
const item = (grantId: string, recordVersion = 1, termsHash = H): GrantSelectionItem => ({ grantId, recordVersion, termsHash });
const SEL = 'U2VsZWN0aW9uUmVxdWVzdA';

describe('P1: the fixture is the reference and the builder matches it', () => {
  it('pins the case set, the prefix, the cap and every byte', () => {
    expect(fixture).toMatchObject({ version: 'hadron-grant-selection-signature-v1', termsVersion: 'hadron-grant-terms-v1', challengeAlgorithm: 'SHA-256', cap: 25 });
    expect(GRANT_SELECTION_PAYLOAD_V1).toBe('hadron-grant-selection-signature-v1');
    expect(GRANT_SELECTION_CAP).toBe(25);
    expect(fixture.cases.map((c) => c.name)).toEqual([
      'one-item', 'three-items-in-request-order', 'three-items-reversed-asked', 'other-selection', 'item-version-moved',
      'byte-order-not-locale', 'at-the-cap-25',
    ]);
    // Independent Python hashlib pin of the compact UTF-8 JSON: a regenerated fixture that moves any byte moves this hash.
    expect(createHash('sha256').update(JSON.stringify(fixture.cases)).digest('hex')).toBe('517c6d81f0bd76b07d0e526da068083b7c1be20cf6c6401d3b69f4d2b73fd840');
  });

  it.each([
    ['one-item'], ['three-items-in-request-order'], ['three-items-reversed-asked'], ['other-selection'], ['item-version-moved'],
    ['byte-order-not-locale'], ['at-the-cap-25'],
  ])('%s: builder bytes equal the fixture bytes', (name) => {
    const c = byName(name);
    const payload = grantSelectionPayloadBytes(GRANT_SELECTION_PAYLOAD_V1, { selectionId: c.selectionId, items: c.items });
    // Independent of the builder: the spec's lines, items ascending by the grant id's bytes, LF after each, no CR.
    const sorted = [...c.items].sort((a, b) => Buffer.compare(Buffer.from(a.grantId), Buffer.from(b.grantId)));
    const literal = `hadron-grant-selection-signature-v1\nselection ${c.selectionId}\n`
      + sorted.map((i) => `grant ${i.grantId}\nversion ${i.recordVersion}\nterms-hash ${i.termsHash}\n`).join('');
    expect(payload.toString('utf8')).toBe(literal);
    expect(payload.toString('utf8')).toBe(c.payloadUtf8);
    expect(payload.toString('base64')).toBe(c.canonical);
    expect(payload.includes(0x0d)).toBe(false);
    expect(signatureChallenge(payload).toString('hex')).toBe(c.challengeHex);
    expect(signatureChallenge(payload).toString('base64url')).toBe(c.challengeBase64url);
  });

  it('the order the grants were asked in never moves a byte, and each binding moves the challenge', () => {
    expect(byName('three-items-reversed-asked').challengeHex).toBe(byName('three-items-in-request-order').challengeHex);
    const base = byName('three-items-in-request-order').challengeHex;
    expect(byName('other-selection').challengeHex).not.toBe(base);
    expect(byName('item-version-moved').challengeHex).not.toBe(base);
  });

  it('orders by byte value, never by locale: uppercase before underscore before lowercase', () => {
    const lines = byName('byte-order-not-locale').payloadUtf8.split('\n').filter((l) => l.startsWith('grant '));
    expect(lines).toEqual(['grant B1', 'grant Z9', 'grant _1', 'grant a1']);
  });

  it('the cap is 25 items, the fixture holds exactly 25, and a 26th is refused', () => {
    expect(byName('at-the-cap-25').items).toHaveLength(25);
    const many = Array.from({ length: 26 }, (_, n) => item(`g${String(n).padStart(2, '0')}`));
    expect(() => grantSelectionPayloadBytes(GRANT_SELECTION_PAYLOAD_V1, { selectionId: SEL, items: many })).toThrow(/at most 25/);
  });
});

describe('P2: the builder refuses, never repairs', () => {
  const build = (p: Partial<{ selectionId: string; items: GrantSelectionItem[] }>) =>
    grantSelectionPayloadBytes(GRANT_SELECTION_PAYLOAD_V1, { selectionId: SEL, items: [item('a1'), item('b1')], ...p });

  it('builds the baseline these refusals perturb', () => {
    expect(build({}).toString('utf8')).toBe(`hadron-grant-selection-signature-v1\nselection ${SEL}\ngrant a1\nversion 1\nterms-hash ${H}\ngrant b1\nversion 1\nterms-hash ${H}\n`);
  });

  it.each([
    ['an empty list', { items: [] }],
    ['a duplicate grant id', { items: [item('a1'), item('a1', 2)] }],
    ['a duplicate with the same pins', { items: [item('a1'), item('b1'), item('a1')] }],
    ['uppercase terms hash', { items: [item('a1', 1, H.toUpperCase())] }],
    ['short terms hash', { items: [item('a1', 1, '0ef8')] }],
    ['version 0', { items: [item('a1', 0)] }],
    ['negative version', { items: [item('a1', -1)] }],
    ['fractional version', { items: [item('a1', 1.5)] }],
    ['unsafe version', { items: [item('a1', 2 ** 53)] }],
    ['a grant id with a space', { items: [item('a 1')] }],
    ['a grant id with LF (a forged line)', { items: [item('a1\nversion 9')] }],
    ['a grant id with CR', { items: [item('a1\r')] }],
    ['a grant id outside visible ASCII', { items: [item('aé')] }],
    ['an empty grant id', { items: [item('')] }],
    ['a selection id of 21 characters', { selectionId: 'U2VsZWN0aW9uUmVxdWVz' }],
    ['a selection id with padding', { selectionId: 'U2VsZWN0aW9uUmVxdWVzdA==' }],
    ['a selection id with a standard-base64 character', { selectionId: 'U2VsZWN0aW9uUmVxdWVz+' }],
    ['an empty selection id', { selectionId: '' }],
  ])('refuses %s', (_, patch) => {
    expect(() => build(patch)).toThrow();
  });

  it('refuses a list that is not a list', () => {
    expect(() => build({ items: undefined as unknown as GrantSelectionItem[] })).toThrow();
    expect(() => build({ items: 'a1' as unknown as GrantSelectionItem[] })).toThrow();
  });

  it('a version this server cannot build is refused, never substituted', () => {
    for (const v of ['hadron-grant-selection-signature-v2', GRANT_SIGNATURE_PAYLOAD_V1, SIGNATURE_PAYLOAD_V3, '']) {
      expect(() => grantSelectionPayloadBytes(v, { selectionId: SEL, items: [item('a1')] })).toThrow(UnsupportedSignaturePayloadError);
    }
  });
});

describe('P3: the three payload versions never stand in for one another', () => {
  it('the v1 builder refuses the selection prefix, and the selection builder refuses the v1 prefix', () => {
    expect(() => grantSignaturePayloadBytes(GRANT_SELECTION_PAYLOAD_V1, { grantId: 'a1', recordVersion: 1, termsHash: H, requestId: SEL })).toThrow(UnsupportedSignaturePayloadError);
    expect(() => grantSelectionPayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, { selectionId: SEL, items: [item('a1')] })).toThrow(UnsupportedSignaturePayloadError);
  });

  it('a selection of one grant and a v1 payload for that grant are different bytes with different challenges', () => {
    const sel = grantSelectionPayloadBytes(GRANT_SELECTION_PAYLOAD_V1, { selectionId: SEL, items: [item('a1')] });
    const one = grantSignaturePayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, { grantId: 'a1', recordVersion: 1, termsHash: H, requestId: SEL });
    expect(sel.equals(one)).toBe(false);
    expect(signatureChallenge(sel).equals(signatureChallenge(one))).toBe(false);
    expect(sel.toString('utf8').startsWith('hadron-grant-selection-signature-v1\n')).toBe(true);
    expect(one.toString('utf8').startsWith('hadron-grant-signature-v1\n')).toBe(true);
  });
});
